//! Items that exist for code generated by `sotu-macros`.
//!
//! Nothing in this module is public API, and it may change in any release.

use crate::Outcome;

/// Marker selecting the hook adapters for functions that take a trailing
/// context parameter.
pub struct WithContext;

/// Marker selecting the hook adapters for functions that take no context
/// parameter.
pub struct WithoutContext;

/// Marker selecting the hook adapters for `async` functions that take a
/// trailing context parameter.
pub struct AsyncWithContext;

/// Marker selecting the hook adapters for `async` functions that take no
/// context parameter.
pub struct AsyncWithoutContext;

/// The result of dispatching an event to a single node.
///
/// Extends [`Outcome`] with the offsets that mounted child machines need to
/// report where a transition is handled or where dispatch continues.
#[derive(Eq, PartialEq, Debug)]
pub enum NodeOutcome<S, X> {
    /// Consume the event.
    Handled,
    /// Defer the event to the parent node.
    Super,
    /// Transition locally to the target.
    Transition(S),
    /// Transition externally to the target.
    ///
    /// `handler_offset` is the number of levels above the visited node at
    /// which the handling node sits, where `0` is the visited node itself.
    ExternalTransition {
        /// The state to transition to.
        target: S,
        /// Levels between the visited node and the handling node.
        handler_offset: usize,
    },
    /// Leave the machine through the given exit point.
    Exit(X),
    /// Skip nodes and continue dispatch `mount_offset` levels above the
    /// visited node.
    DeferToMount {
        /// Levels between the visited node and the node to continue at.
        mount_offset: usize,
    },
}

impl<S, X> From<Outcome<S, X>> for NodeOutcome<S, X> {
    fn from(outcome: Outcome<S, X>) -> Self {
        match outcome {
            Outcome::Handled => Self::Handled,
            Outcome::Super => Self::Super,
            Outcome::Transition(target) => Self::Transition(target),
            Outcome::ExternalTransition(target) => Self::ExternalTransition {
                target,
                handler_offset: 0,
            },
            Outcome::Exit(exit) => Self::Exit(exit),
        }
    }
}

impl<S, X> NodeOutcome<S, X> {
    /// Map the target of a `Transition` or `ExternalTransition` with `map`.
    ///
    /// All other variants are returned unchanged.
    pub fn map_state<T>(self, map: impl FnOnce(S) -> T) -> NodeOutcome<T, X> {
        match self {
            Self::Handled => NodeOutcome::Handled,
            Self::Super => NodeOutcome::Super,
            Self::Transition(target) => NodeOutcome::Transition(map(target)),
            Self::ExternalTransition {
                target,
                handler_offset,
            } => NodeOutcome::ExternalTransition {
                target: map(target),
                handler_offset,
            },
            Self::Exit(exit) => NodeOutcome::Exit(exit),
            Self::DeferToMount { mount_offset } => NodeOutcome::DeferToMount { mount_offset },
        }
    }
}

/// The mode-neutral view of a generated machine.
///
/// Parent code names a child's types through this trait, as in
/// `<C as Submachine>::State`, regardless of the mode of either machine.
pub trait Submachine: Sized {
    /// The event type handled by the machine.
    type Event;

    /// The context handed to every handler, entry action and exit action.
    type Context<'ctx, 'data: 'ctx>;

    /// The leaf states of the machine.
    type State;

    /// The superstates of the machine, borrowing local storage from the active
    /// leaf state for `'sub`.
    ///
    /// The bound `Self: 'sub` covers every parameter the state type can
    /// mention, because every parameter of an implementation appears in `Self`.
    type Superstate<'sub>
    where
        Self: 'sub;

    /// The exit points through which the machine can be left.
    type Exit;

    /// Return the state the machine starts in.
    fn initial() -> Self::State;
}

/// Marker for generated machines that run in blocking mode.
///
/// A blocking parent requires this trait of its children, so its diagnostic is
/// the one a user sees when mounting an awaitable child.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is an awaitable state machine and can not be mounted in a blocking one",
    note = "add `awaitable` to the parent's `#[state_machine]`"
)]
pub trait BlockingSubmachine: Submachine + crate::blocking::IntoStateMachine {}

/// Marker for generated machines that can not be left through an exit point.
///
/// Implemented for machines whose [`Submachine::Exit`] is
/// [`core::convert::Infallible`]. A parent that mounts a child without an exit
/// handler requires this trait of the child, since an exit it can not handle
/// would otherwise go unhandled.
#[diagnostic::on_unimplemented(
    message = "submachine `{Self}` can exit",
    note = "declare `exit_handler = …` on `#[submachine]`"
)]
pub trait ExitlessSubmachine: Submachine<Exit = core::convert::Infallible> {}

/// The awaitable view of a generated machine, through which an awaitable
/// parent calls its mounted children.
///
/// Every machine that `#[state_machine]` generates implements this trait: an
/// awaitable machine natively, and a blocking machine through futures that are
/// ready on their first poll when the macros' `async` feature is enabled. An
/// awaitable parent therefore mounts a child of either mode without naming
/// the child's mode.
///
/// The trait is not part of the public API and is exempt from semver. Only the
/// code that `#[state_machine]` generates implements it, and it may change in
/// any release.
///
/// Depths count levels from the top: a top-level node has depth `1`.
#[cfg(feature = "async")]
pub trait AwaitableSubmachine: Submachine {
    /// Return the superstate enclosing `state`, if there is one.
    ///
    /// The superstate may borrow the local storage of `state`.
    fn state_superstate<'sub>(state: &'sub mut Self::State) -> Option<Self::Superstate<'sub>>
    where
        Self: 'sub;

    /// Return whether `first` and `second` are the same leaf state.
    fn state_same(first: &Self::State, second: &Self::State) -> bool;

    /// Return whether `first` and `second` are the same superstate.
    fn superstate_same<'first, 'second>(
        first: &Self::Superstate<'first>,
        second: &Self::Superstate<'second>,
    ) -> bool
    where
        Self: 'first + 'second;

    /// Return the depth of `state`, counting itself.
    fn state_depth(state: &mut Self::State) -> usize;

    /// Return whether `state` is addressed by `event`, together with `event`.
    fn state_is_addressed(state: &Self::State, event: Self::Event) -> (bool, Self::Event);

    /// Return whether `superstate` is addressed by `event`, together with
    /// `event`.
    fn superstate_is_addressed<'sub>(
        superstate: &Self::Superstate<'sub>,
        event: Self::Event,
    ) -> (bool, Self::Event)
    where
        Self: 'sub;

    /// Return the depth of `superstate`, counting itself.
    ///
    /// A borrowed superstate can not be walked to count its levels, so the
    /// depth is a property of the variant of `superstate`: the length of its
    /// declared chain of enclosing nodes. For a superstate of a mounted child
    /// it is the depth of the mount node plus the depth of the child's
    /// superstate inside the child.
    fn superstate_depth<'sub>(superstate: &Self::Superstate<'sub>) -> usize
    where
        Self: 'sub;

    /// Consume `superstate` and return the superstate enclosing it, if there is
    /// one.
    ///
    /// A borrowed superstate can not be walked upwards by borrowing it once
    /// per level, since a future that awaits while holding such a chain would
    /// have to be recursive. Consuming each superstate keeps exactly one of
    /// the chain alive.
    ///
    /// The parent has the lifetime of `superstate`, so storage that
    /// `superstate` borrows from the active leaf state moves into the parent.
    fn superstate_parent<'sub>(
        superstate: Self::Superstate<'sub>,
    ) -> Option<Self::Superstate<'sub>>
    where
        Self: 'sub;

    /// Dispatch `event` to `state` alone.
    ///
    /// Resolves to the outcome of the state together with the event it was
    /// produced for.
    fn dispatch_state<'ctx, 'data: 'ctx>(
        state: &mut Self::State,
        shared_storage: &mut Self,
        event: Self::Event,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = Dispatched<Self::State, Self::Exit, Self::Event>>;

    /// Dispatch `event` to `superstate` alone.
    ///
    /// Resolves to the outcome of the superstate together with the event it
    /// was produced for.
    fn dispatch_superstate<'ctx, 'data: 'ctx, 'sub>(
        superstate: &mut Self::Superstate<'sub>,
        shared_storage: &mut Self,
        event: Self::Event,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = Dispatched<Self::State, Self::Exit, Self::Event>>
    where
        Self: 'sub;

    /// Run the entry action of `state`.
    fn enter_state<'ctx, 'data: 'ctx>(
        state: &mut Self::State,
        shared_storage: &mut Self,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = ()>;

    /// Run the exit action of `state`.
    fn exit_state<'ctx, 'data: 'ctx>(
        state: &mut Self::State,
        shared_storage: &mut Self,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = ()>;

    /// Run the entry action of `superstate`.
    fn enter_superstate<'ctx, 'data: 'ctx, 'sub>(
        superstate: &mut Self::Superstate<'sub>,
        shared_storage: &mut Self,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = ()>
    where
        Self: 'sub;

    /// Run the exit action of `superstate`.
    fn exit_superstate<'ctx, 'data: 'ctx, 'sub>(
        superstate: &mut Self::Superstate<'sub>,
        shared_storage: &mut Self,
        context: &mut Self::Context<'ctx, 'data>,
    ) -> impl Future<Output = ()>
    where
        Self: 'sub;
}

/// A [`NodeOutcome`] together with the event it was produced for.
///
/// Dispatch hooks take the event by value so that mount boundaries can move it
/// into a child's event type, and they hand it back through this type.
#[derive(Eq, PartialEq, Debug)]
pub struct Dispatched<S, X, E> {
    /// What the visited node decided to do with the event.
    pub outcome: NodeOutcome<S, X>,
    /// The event that was dispatched.
    pub event: E,
}

// MARK: Mount Fields

/// Access to the parent field that stores a mounted submachine `C`.
///
/// The macro can not see a field's type, so it resolves the storage kind
/// through this trait. A field of type `C` is persistent storage: the child
/// keeps its value across activations of its mount node. A field of type
/// `Option<C>` holds one instance per activation: it is `Some` exactly while
/// its mount node is active and `None` otherwise.
///
/// The two implementations do not overlap even when `C` is itself an
/// `Option`, because the trait parameter differs between them.
#[diagnostic::on_unimplemented(
    message = "field of type `{Self}` can not hold submachine `{C}`",
    note = "a submachine field must have type `{C}` (persistent) or `Option<{C}>` (one instance per activation)"
)]
pub trait MountField<C> {
    /// Borrow the stored submachine, or return `None` if the field holds no
    /// instance.
    ///
    /// A persistent field always returns `Some`. An instance field returns
    /// `Some` exactly while its mount node is active.
    fn get(&self) -> Option<&C>;

    /// Mutably borrow the stored submachine, or return `None` if the field
    /// holds no instance.
    ///
    /// A persistent field always returns `Some`. An instance field returns
    /// `Some` exactly while its mount node is active.
    fn get_mut(&mut self) -> Option<&mut C>;

    /// Release the stored submachine when its mount node is exited.
    ///
    /// An instance field drops its instance and becomes `None`, so it is
    /// `None` whenever its mount node is inactive. A persistent field keeps
    /// its value unchanged.
    fn release(&mut self);
}

impl<C> MountField<C> for C {
    fn get(&self) -> Option<&C> {
        Some(self)
    }

    fn get_mut(&mut self) -> Option<&mut C> {
        Some(self)
    }

    fn release(&mut self) {}
}

impl<C> MountField<C> for Option<C> {
    fn get(&self) -> Option<&C> {
        self.as_ref()
    }

    fn get_mut(&mut self) -> Option<&mut C> {
        self.as_mut()
    }

    fn release(&mut self) {
        *self = None;
    }
}

/// Creation of a default submachine `C` in the parent field that stores it.
///
/// A mount node without a factory fills its field through this trait on
/// entry, so that an instance field of type `Option<C>` is `Some` exactly
/// while its mount node is active. Only instance fields require
/// `C: Default`; a persistent field of type `C` already holds its child.
#[diagnostic::on_unimplemented(
    message = "`{C}` does not implement `Default`",
    note = "declare `factory = …` on `#[submachine]` or store it in a field of type `{C}`"
)]
pub trait DefaultInstance<C> {
    /// Store `C::default()` in an empty instance field when its mount node
    /// is entered.
    ///
    /// An instance field that already holds an instance keeps it. A
    /// persistent field keeps its value unchanged.
    fn fill_default(&mut self);
}

impl<C> DefaultInstance<C> for C {
    fn fill_default(&mut self) {}
}

impl<C: Default> DefaultInstance<C> for Option<C> {
    fn fill_default(&mut self) {
        if self.is_none() {
            *self = Some(C::default());
        }
    }
}

/// Creation of a submachine `C` through a factory in the parent field that
/// stores it.
///
/// A mount node with a factory fills its field through this trait on entry,
/// calling the factory only while the field is vacant. Only instance fields
/// of type `Option<C>` implement it, since a persistent field of type `C`
/// already holds its child and is never created by the machine.
#[diagnostic::on_unimplemented(
    message = "`factory` requires an `Option<{C}>` field",
    note = "a `{C}` field is never created by the machine"
)]
pub trait FactoryInstance<C> {
    /// Return whether the field holds no instance, so that entering the mount
    /// node calls the factory.
    fn is_vacant(&self) -> bool;

    /// Store `instance`, created by the factory, in the field.
    fn install(&mut self, instance: C);
}

impl<C> FactoryInstance<C> for Option<C> {
    fn is_vacant(&self) -> bool {
        self.is_none()
    }

    fn install(&mut self, instance: C) {
        *self = Some(instance);
    }
}
